import type { OnboardingMedia } from '../types';
import onboardingMedia from './onboardingMedia.json';

/**
 * Maps an activity id (see activities.ts) to its background clip + poster on Cloudinary.
 *
 * onboardingMedia.json is generated by the server's media:compress + media:upload
 * scripts (see docs/phase-reports/phase-02c-onboarding-media.txt) — never edit it by
 * hand. Only URLs are bundled; the video files themselves never are. Every activity
 * has a clip except 'other_activity', which intentionally has none.
 */
export const ACTIVITY_VIDEO_MAP: Partial<Record<string, OnboardingMedia>> = Object.fromEntries(
  Object.entries(onboardingMedia).map(([activityId, { video, poster }]) => [activityId, { video, poster }]),
);
